=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to detect which kind of drive off shall be considered in case 
   there are several possibilities */

// Highest priority Comfort Release (Driver is typically on brake and it should not overlap with torque balance use case)
if(		in_CsmHoldComfortReleaseActive == true
	||	(	in_CsmHoldDrvOffTrqSuffActive == true
		&&	CsmHoldComfortReleaseActiveK1 == true))
{
	CsmDriveOffType = CSMDrvOffType_ComfortRelease;
	CsmHoldDriveOffATarBrk = CsmHoldComfortReleaseATarBrk.min(CsmHoldDrvOffTrqSuffATarBrk);
	CsmHoldDrvOffTrqSuffActive = false;
	CsmHoldDrvOffTrqBalActive = false;
	CsmHoldComfortReleaseActive = true;
	CsmHoldDrvOffActive = true;

// Torque Sufficient less priority
}else if(	in_CsmHoldDrvOffTrqSuffActive == true
		&&	CsmDriveOffType != CSMDrvOffType_TorqueBalance)
{
	CsmDriveOffType = CSMDrvOffType_TorqueSufficient;
	CsmHoldDriveOffATarBrk = CsmHoldDrvOffTrqSuffATarBrk;
	CsmHoldDrvOffTrqSuffActive = true;
	CsmHoldDrvOffTrqBalActive = false;
	CsmHoldComfortReleaseActive = false;
	CsmHoldDrvOffActive = true;	
// Torque Balanced shall have higher priority (Torque Balanced can anyway only be triggered if all functions enables it)
}else if(in_CsmHoldDrvOffTrqBalActive == true)
{
	CsmDriveOffType = CSMDrvOffType_TorqueBalance;
	CsmHoldDriveOffATarBrk = CsmHoldDrvOffTrqBalATarBrk;
	CsmHoldDrvOffTrqSuffActive = false;
	CsmHoldDrvOffTrqBalActive = true;
	CsmHoldComfortReleaseActive = false;
	CsmHoldDrvOffActive = true;

}else
{
	CsmDriveOffType = CSMDrvOffType_NotActive;
	CsmHoldDriveOffATarBrk = 0;
	CsmHoldDrvOffTrqSuffActive = false;
	CsmHoldDrvOffTrqBalActive = false;
	CsmHoldComfortReleaseActive = false;
	CsmHoldDrvOffActive = false;
}

if(		CsmHoldDrvOffTrqSuffEnableReactByBrkInc == true
	&&	CsmHoldDrvOffTrqBalEnableReactByBrkInc == true
	&&	CsmHoldComfortReleaseEnableReactByBrkInc == true)
{
	CsmHoldDrvOffEnableReactByBrkInc = true;
}else
{
	CsmHoldDrvOffEnableReactByBrkInc = false;
}


//Storage
CsmHoldComfortReleaseActiveK1 = CsmHoldComfortReleaseActive;


=== Method: CsmDriveOffType (AbstractMethod) ===
return CsmDriveOffType;


=== Method: CsmHoldComfortReleaseActive (AbstractMethod) ===
return CsmHoldComfortReleaseActive;


=== Method: CsmHoldDriveOffATarBrk (AbstractMethod) ===
return CsmHoldDriveOffATarBrk;


=== Method: CsmHoldDrvOffActive (AbstractMethod) ===
return CsmHoldDrvOffActive;


=== Method: CsmHoldDrvOffEnableReactByBrkInc (AbstractMethod) ===
return CsmHoldDrvOffEnableReactByBrkInc;


=== Method: CsmHoldDrvOffTrqBalActive (AbstractMethod) ===
